// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller) public {
        vm.assume(_caller != address(0)); // avoid zero address issues
        vm.prank(_caller);
        bool result = c.logSetupFailed();
        assertTrue(result == c.approvedToLog(_caller));
    }
}

